/// <reference path="../pb_data/types.d.ts" />

// Invitations of members to hunts, with their answers. `token` identifies
// the member's personal answer link: random, generated by the server, see
// pb_hooks/invitations.pb.js. Deleted with their hunt or member (right to
// erasure).
migrate(
  (app) => {
    const organizerOnly = '@request.auth.collectionName = "organizers"';
    const collection = new Collection({
      type: "base",
      name: "invitations",
      listRule: organizerOnly,
      viewRule: organizerOnly,
      createRule: organizerOnly,
      updateRule: organizerOnly,
      deleteRule: organizerOnly,
    });
    collection.fields.add(
      new RelationField({
        name: "hunt",
        required: true,
        collectionId: app.findCollectionByNameOrId("hunts").id,
        maxSelect: 1,
        cascadeDelete: true,
      }),
      new RelationField({
        name: "member",
        required: true,
        collectionId: app.findCollectionByNameOrId("members").id,
        maxSelect: 1,
        cascadeDelete: true,
      }),
      new TextField({
        name: "token",
        required: true,
        min: 32,
        max: 64,
        pattern: "^[A-Za-z0-9]+$",
      }),
      new SelectField({
        name: "participation",
        required: true,
        maxSelect: 1,
        values: ["pending", "present", "waiting_list", "absent"],
      }),
      new DateField({ name: "answered_at" }),
      new SelectField({
        name: "answered_via",
        maxSelect: 1,
        values: ["sms", "web", "manual"],
      }),
      new AutodateField({ name: "created", onCreate: true }),
      new AutodateField({ name: "updated", onCreate: true, onUpdate: true }),
    );
    collection.addIndex("idx_invitations_token", true, "token", "");
    collection.addIndex(
      "idx_invitations_hunt_member",
      true,
      "hunt, member",
      "",
    );
    app.save(collection);
  },
  (app) => {
    app.delete(app.findCollectionByNameOrId("invitations"));
  },
);
